export type VoteCount = z.infer<typeof VoteCount>;

/** Props of each of the package's pages by URL pattern below the mount, as its C# loader returns them: `definePage(pages['/articles/[slug]'], Page)`. */
export const pages = {
  "/": HomeProps,
  "/articles/[slug]": ArticleProps,
  "/contact": z.object({}),
} as const;

/** The app's shared props (`NetjesOptions.UseSharedProps`), which a page package does not know. */
export const sharedProps = z.unknown();

/** JSON endpoints mapped through the mount, by method and route below it: what they accept and return. */
export const api = {
  "POST /feedback": { request: FeedbackNote, response: FeedbackReceipt },
} as const;

/**
 * What the package's endpoints read from their URLs, by method and route below the mount as in `api`: the route
 * values below the mount, then the query string values the handler binds. A JSON endpoint has a key for each of
 * its methods except HEAD, and any other endpoint one for GET, if it answers GET.
 */
export type EndpointParams = {
  "GET /articles/{slug}/feed": { slug: string; take?: number | null | undefined };
  "POST /feedback": Record<string, never>;
};
export type EndpointKey = keyof EndpointParams;
const endpointTemplates: Record<EndpointKey, string> = {
  "GET /articles/{slug}/feed": "/articles/{slug}/feed",
  "POST /feedback": "/feedback",
};

/**
 * The URL below the mount of one of the package's endpoints, with its values encoded: `endpointUrl('GET /search', { q })`.
 * The values the route does not name go in the query string, followed by the third argument. Pass it through this
 * file's `useHref`, which puts the mount and the base path in front, for a `fetch` or an `<a href>`.
 */
export function endpointUrl<K extends EndpointKey>(
  key: K,
  ...args: {} extends EndpointParams[K]
    ? [params?: EndpointParams[K], search?: SearchParamsInput]
    : [params: EndpointParams[K], search?: SearchParamsInput]
): string {
  return buildEndpointUrl(endpointTemplates[key], args[0] ?? {}, args[1], key);
}

